('ose.spell.clerigo_protecao_contra_o_mal','Proteção contra o Mal',1,FALSE,FALSE,'advanced','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_protecao_contra_o_mal","name":"Proteção contra o Mal","nameEn":"Protection from Evil","className":"clerigo","circle":1,"range":"O conjurador","duration":"12 turnos","reversible":false,"description":"Uma barreira sagrada concede +1 em testes de proteção e -1 na CA contra ataques de monstros malignos e impede ataques naturais de criaturas invocadas.","system_id":"ose"}'::jsonb,'ose'),
('ose.spell.clerigo_purificar_comida','Purificar Comida e Água',1,FALSE,FALSE,'advanced','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_purificar_comida","name":"Purificar Comida e Água","nameEn":"Purify Food and Water","className":"clerigo","circle":1,"range":"3m","duration":"Permanente","reversible":false,"description":"Torna potável e segura comida e água estragada ou envenenada para até 12 pessoas.","system_id":"ose"}'::jsonb,'ose'),
