('ose.spell.clerigo_resistir_frio','Resistir ao Frio',1,FALSE,FALSE,'advanced','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_resistir_frio","name":"Resistir ao Frio","nameEn":"Resist Cold","className":"clerigo","circle":1,"range":"9m","duration":"6 turnos","reversible":false,"description":"Protege contra o frio extremo não-mágico e concede bônus de +2 em testes de resistência contra frio mágico e sopro de dragão branco.","system_id":"ose"}'::jsonb,'ose'),
